import{_ as a,o as t,c as i,a8 as o}from"./chunks/framework.CNIpabDg.js";const d=JSON.parse(`{"title":"Run a guest from Xila's terminal","description":"Launch or install a WASI guest through the mounted Xila WASM executable.","frontmatter":{"layout":"doc","docType":"how-to","description":"Launch or install a WASI guest through the mounted Xila WASM executable."},"headers":[],"relativePath":"how-to/run-guest.md","filePath":"how-to/run-guest.md","lastUpdated":1792762708000}`),l={name:"how-to/run-guest.md"};function r(s,e,n,c,u,h){return t(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792762708000"},[...e[0]||(e[0]=[o('<h1 id="run-a-guest-from-xila-s-terminal" tabindex="-1">Run a guest from Xila&#39;s terminal <a class="header-anchor" href="#run-a-guest-from-xila-s-terminal" aria-label="Permalink to &quot;Run a guest from Xila&#39;s terminal&quot;">​</a></h1><p>Launch a guest already present in Xila&#39;s virtual filesystem, or invoke its installer to register application resources.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><ul><li>Start an Xila runtime with <code>/applications/executables/wasm</code> mounted, such as the native or browser example.</li><li>Place a compatible guest in the VFS as a regular file. The browser example includes <code>/applications/executables/calculator</code>; it has no general guest upload mechanism.</li><li>Check the guest&#39;s required imports against the <a href="/reference/wasm-runtime.html">runtime</a> and <a href="/reference/graphics-bindings.html">graphics</a> references.</li></ul><h2 id="launch-the-application" tabindex="-1">Launch the application <a class="header-anchor" href="#launch-the-application" aria-label="Permalink to &quot;Launch the application&quot;">​</a></h2><p>Open Xila&#39;s graphical terminal and enter an absolute VFS path:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/applications/executables/wasm /applications/executables/calculator</span></span></code></pre></div><p>For another guest, replace <code>/applications/executables/calculator</code> with its path in Xila&#39;s VFS. This command runs in <strong>Xila&#39;s terminal</strong>, not your host shell.</p><p>Normal execution calls <code>_start: () -&gt; ()</code>. The loader reads the supplied path directly; use an absolute VFS path rather than relying on <code>Current_directory</code> resolution inside the WASM loader.</p><h2 id="run-an-installer" tabindex="-1">Run an installer <a class="header-anchor" href="#run-an-installer" aria-label="Permalink to &quot;Run an installer&quot;">​</a></h2><p>For a guest providing <code>__install: () -&gt; ()</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/applications/executables/wasm --install /applications/executables/calculator</span></span></code></pre></div><p>The browser example runs Calculator&#39;s installer during boot, so its application-drawer shortcut is normally already present. A missing or incorrectly typed installer export fails without launching the application&#39;s main entrypoint.</p><h2 id="verify-completion" tabindex="-1">Verify completion <a class="header-anchor" href="#verify-completion" aria-label="Permalink to &quot;Verify completion&quot;">​</a></h2><p>Check the guest&#39;s expected output or interface and the terminal for reported errors. For Calculator, evaluate <code>1 + 2 = 3</code> and close its window; the desktop should remain usable. For an installer, check the resource it is documented to create, such as Calculator&#39;s shortcut.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li>Missing file: verify the path is in Xila&#39;s VFS, not just on the host computer.</li><li>Entry/import errors: rebuild the guest with the required target and compatible supported imports.</li><li>Unsupported graphics call: check the supported call subset before assuming enabling <code>graphics</code> provides the entire LVGL API.</li></ul><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="./build-guest.html">Build a guest application</a>.</li><li><a href="/explanation/architecture/executables/wasm.html">Wasmi execution model</a>.</li></ul>',19)])])}const m=a(l,[["render",r]]);export{d as __pageData,m as default};
